insert into public.vocabulary (id,word,pronunciation,part_of_speech,meanings,common_phrases,examples,difficulty,tags) select id,word,pronunciation,part_of_speech,meanings,common_phrases,examples,difficulty,tags from public.vocabulary_import_stage on conflict (id) do update set word=excluded.word, pronunciation=excluded.pronunciation, part_of_speech=excluded.part_of_speech, meanings=excluded.meanings, common_phrases=excluded.common_phrases, examples=excluded.examples, difficulty=excluded.difficulty, tags=excluded.tags;
insert into public.exercise_questions (id,word_id,context,sentence,options,correct_answer,sort_order) select id,word_id,context,sentence,options,correct_answer,sort_order from public.exercise_questions_import_stage on conflict (id) do update set word_id=excluded.word_id, context=excluded.context, sentence=excluded.sentence, options=excluded.options, correct_answer=excluded.correct_answer, sort_order=excluded.sort_order;
insert into public.topic_vocabulary (topic_id,vocabulary_id,sort_order) select topic_id,vocabulary_id,sort_order from public.topic_vocabulary_import_stage on conflict (topic_id,vocabulary_id) do update set sort_order=excluded.sort_order;
